create or replace function public.apply_representative_rule_suite_v1(p_doc jsonb,p_suite_code text default 'representative-rule-suite-v1') returns jsonb language sql stable security invoker set search_path='public','pg_catalog' as $function$ select jsonb_set(p_doc,'{document_graph,representative_rule_suite_v1}',public.audit_representative_rule_suite_v1(p_suite_code),true); $function$;
create or replace function public.analyze_text_structural_shadow_v19(p_text text,p_release_code text default 'runtime-structural-v1.19') returns jsonb language plpgsql stable security invoker set search_path='public','pg_catalog' as $function$ declare v_doc jsonb; begin v_doc:=public.analyze_text_structural_shadow_v18(p_text,p_release_code); v_doc:=public.apply_representative_rule_suite_v1(v_doc,'representative-rule-suite-v1'); return v_doc; end; $function$;
